        /// <summary>
        /// Known product name -> its SVG; otherwise a green letter-monogram badge. cssClass lets
        /// each page size the monogram to match its own icon wrapper (e.g. 22px vs 24px).
        /// </summary>
        public static MarkupString IconFor(string name, string cssClass = "farm-icon-monogram")
        {
            var key = name?.Trim() ?? string.Empty;
            if (!string.IsNullOrEmpty(key) && Svgs.TryGetValue(key, out var svg))
                return new MarkupString(svg);

            var letter = string.IsNullOrWhiteSpace(key) ? "?" : char.ToUpperInvariant(key[0]).ToString();
            return new MarkupString($"<span class=\"{cssClass}\">{letter}</span>");
        }
    }
